const t = (r: any) => r.kind === "foreground" ? (r.stdout.text + (r.stderr.text || "")) : JSON.stringify(r);
const U = "D:\\Users\\jjq21\\AppData\\Local\\Programs\\DeepSeek Harness\\resources\\app.asar.unpacked\\dsh";
const NM = "C:\\Users\\jjq21\\.dsh\\profiles\\desktop\\node_modules\\";

const [unpacked, gp, gf] = await Promise.all([
 tools.pwsh({ command: `Get-ChildItem -Force '${U}' -ErrorAction SilentlyContinue | Select-Object Mode,Name | Format-Table -AutoSize | Out-String -Width 200`, description: "List unpacked dsh directory" }),
 tools.grep({ pattern: "sidebar|sidebarItem|navItem|工作区", path: NM + "dsh-pocket" }),
 tools.grep({ pattern: "sidebar|sidebarItem|navItem|工作区|slot", path: NM + "dsh-our-free-model\\client.js" }),
]);
